    r'AWS_ACCESS_KEY_ID': '<AWS_ACCESS_KEY_PLACEHOLDER>',
    r'AWS_SECRET_ACCESS_KEY': '<AWS_SECRET_ACCESS_KEY_PLACEHOLDER>',
