    r'WORKSPACE_SLUG': '<WORKSPACE_SLUG_PLACEHOLDER>',
    r'DATABASE_PASSWORD': '<DB_PASSWORD_PLACEHOLDER>',
    r'API_KEY': '<API_KEY_PLACEHOLDER>',
}

def sanitize_log_object(log_data):
    def replace_key(match):
        key = match.group(0)
        return SENSITIVE_PATTERNS.get(key, key)

    # Recursively sanitize strings within the log object
    def sanitize_value(value):
        if isinstance(value, str):
            for pattern, placeholder in SENSITIVE_PATTERNS.items():
                value = re.sub(pattern, placeholder, value)
            return value
        elif isinstance(value, dict):
            return {k: sanitize_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [sanitize_value(item) for item in value]
        return value

    return sanitize_value(log_data)
